package com.gcu.va.entity;

import java.time.LocalDate;
import java.time.LocalDateTime;

import jakarta.persistence.*;

/**
 * Represents an action-plan task or preparation checklist item.
 *
 * Each task belongs to a specific veteran. A task may optionally
 * be associated with one of that veteran's goals.
 *
 * Tasks are personal planning tools and do not represent official
 * VA requirements or eligibility determinations.
 */
@Entity
@Table(name = "action_tasks")
public class ActionTask {

    // Unique identifier generated by the database.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Name of the task.
    @Column(nullable = false, length = 150)
    private String title;

    // Optional details or notes about the task.
    @Column(length = 1000)
    private String description;

    // Optional target date for completing the task.
    private LocalDate targetDate;

    // Current progress status.
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private TaskStatus status;

    // Identifies whether this is an action-plan task or checklist item.
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private TaskType taskType;

    // Records when the task was created.
    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt;

    // Veteran who owns the task.
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "veteran_id", nullable = false)
    private Veteran veteran;

    // Optional goal associated with the task.
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "goal_id")
    private Goal goal;

    /**
     * Initializes default values before the task is first saved.
     */
    @PrePersist
    protected void onCreate() {
        if (createdAt == null) {
            createdAt = LocalDateTime.now();
        }

        if (status == null) {
            status = TaskStatus.NOT_STARTED;
        }
    }

    /**
     * Retrieves the task identifier.
     *
     * @return the task ID
     */
    public Long getId() {
        return id;
    }

    /**
     * Sets the task identifier.
     *
     * @param id the task ID
     */
    public void setId(Long id) {
        this.id = id;
    }

    /**
     * Retrieves the task title.
     *
     * @return the task title
     */
    public String getTitle() {
        return title;
    }

    /**
     * Sets the task title.
     *
     * @param title the task title
     */
    public void setTitle(String title) {
        this.title = title;
    }

    /**
     * Retrieves the task description.
     *
     * @return the task description
     */
    public String getDescription() {
        return description;
    }

    /**
     * Sets the task description.
     *
     * @param description the task description
     */
    public void setDescription(String description) {
        this.description = description;
    }

    /**
     * Retrieves the target completion date.
     *
     * @return the target date, or null if none was set
     */
    public LocalDate getTargetDate() {
        return targetDate;
    }

    /**
     * Sets the target completion date.
     *
     * @param targetDate the target date
     */
    public void setTargetDate(LocalDate targetDate) {
        this.targetDate = targetDate;
    }

    /**
     * Retrieves the task's progress status.
     *
     * @return the task status
     */
    public TaskStatus getStatus() {
        return status;
    }

    /**
     * Sets the task's progress status.
     *
     * @param status the status to assign
     */
    public void setStatus(TaskStatus status) {
        this.status = status;
    }

    /**
     * Retrieves the task type.
     *
     * @return the task type
     */
    public TaskType getTaskType() {
        return taskType;
    }

    /**
     * Sets the task type.
     *
     * @param taskType the task type
     */
    public void setTaskType(TaskType taskType) {
        this.taskType = taskType;
    }

    /**
     * Retrieves the creation timestamp.
     *
     * @return the creation date and time
     */
    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    /**
     * Sets the creation timestamp.
     *
     * @param createdAt the creation date and time
     */
    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }

    /**
     * Retrieves the veteran who owns this task.
     *
     * @return the associated veteran
     */
    public Veteran getVeteran() {
        return veteran;
    }

    /**
     * Associates the task with its owner.
     *
     * @param veteran the owning veteran
     */
    public void setVeteran(Veteran veteran) {
        this.veteran = veteran;
    }

    /**
     * Retrieves the goal associated with this task.
     *
     * @return the associated goal, or null if unassociated
     */
    public Goal getGoal() {
        return goal;
    }

    /**
     * Associates this task with a goal.
     *
     * @param goal the goal to associate with the task
     */
    public void setGoal(Goal goal) {
        this.goal = goal;
    }
}